 "content": "def transform(grid):
    """Reflect the color-4 figure across its outer edge, using color 6 as an axis cue."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = {v: [(r, c) for r in range(h) for c in range(w) if grid[r][c] == v]
              for v in (4, 6)}
    fig, cue = points[4], points[6]
    if not fig or not cue:
        return out
    r0, r1 = min(r for r, c in fig), max(r for r, c in fig)
    c0, c1 = min(c for r, c in fig), max(c for r, c in fig)
    cr0, cr1 = min(r for r, c in cue), max(r for r, c in cue)
    cc0, cc1 = min(c for r, c in cue), max(c for r, c in cue)
    cue_h, cue_w = cr1 - cr0 + 1, cc1 - cc0 + 1

    # A wider cross cue selects a horizontal reflection axis (copy downward);
    # a T-shaped cue selects a vertical axis (copy to the right).
    if cue_w > cue_h:
        for r, c in fig:
            rr = 2 * r1 + 1 - r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        for r, c in fig:
            cc = 2 * c1 + 1 - c
            if 0 <= cc < w:
                out[r][cc] = 4
    for r, c in cue:
        out[r][c] = 0
    return out
